import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>كل صورة في أجهزتك تعيش في صيغة، وليست كل الصيغ متوافقة مع بعضها. صورة HEIC من آيفون قد لا تفتح في برنامج قديم، وWebP قد ترفضه بوابة توظيف.</p>\n<p>محول الصور يحل هذه المشكلة. يقرأ ملفًا بصيغة ويكتبه بصيغة أخرى، دون أن يغادر جهازك.</p>\n<p>يشرح هذا الدليل كيف يعمل تحويل الصور، وأي الصيغ تختار، والأخطاء التي يجب تجنبها.</p>\n<h2 id=\"what-is-an-image-converter\">ما هو محول الصور؟</h2>\n<p>محول الصور أداة تقرأ ملف صورة بصيغة وتكتبه بصيغة أخرى. مثلًا، يحوّل صورة HEIC من آيفون إلى JPG يعمل في كل مكان.</p>\n<p>التحويل لا يغيّر محتوى الصورة، بل طريقة حفظها. الصورة نفسها تبقى، لكن ملفها يصبح متوافقًا مع البرامج التي تحتاجه.</p>\n<h2 id=\"formats-the-converter-handles\">ما الصيغ التي يدعمها المحول؟</h2>\n<p>المحول يدعم JPG وPNG وWebP وHEIC وSVG وBMP وGIF وAVIF. هذه الصيغ تغطي معظم الصور التي ستصادفها في حياتك اليومية.</p>\n<p>بعض الصيغ لها حدود: SVG صيغة متجهة تحتاج معالجة خاصة، وHEIC يحتاج فك تشفير قبل التحويل. الأداة تتعامل مع كل ذلك تلقائيًا.</p>\n<h2 id=\"how-browser-conversion-works\">كيف يعمل التحويل في المتصفح؟</h2>\n<p>يعمل التحويل في المتصفح بقراءة ملفك وفك تشفيره ثم إعادة ترميزه بالصيغة الجديدة. كل ذلك يحدث على جهازك دون رفع الملف إلى خادم.</p>\n<p>لأن المعالجة محلية، تبقى صورك خاصة. لا أحد يرى ملفاتك، ولا تُحفظ نسخ منها في أي مكان.</p>\n<h2 id=\"choosing-the-right-output-format\">كيف تختار صيغة الإخراج الصحيحة؟</h2>\n<p>لاختيار صيغة الإخراج الصحيحة، اسأل نفسك: أين ستُستخدم الصورة؟ للبوابات والتوافق الكامل اختر JPG، وللشفافية اختر PNG أو WebP.</p>\n<p>للصور الفوتوغرافية اختر JPG أو WebP، وللنصوص والرسوم اختر PNG. الصيغة الصحيحة تعتمد على المحتوى والوجهة معًا.</p>\n<h2 id=\"quality-settings-explained\">إعدادات الجودة مشروحة</h2>\n<p>إعدادات الجودة تتحكم في التوازن بين حجم الملف ووضوح الصورة. جودة 80 إلى 90 مناسبة لمعظم الاستخدامات، و95 للجودة القصوى.</p>\n<p>التحويل إلى صيغة دون فقدان مثل PNG يتجاهل إعداد الجودة. أما التحويل إلى JPG أو WebP فيستخدمه لتحديد مقدار الضغط.</p>\n<h2 id=\"transparency-and-matte-fill\">الشفافية ولون التعبئة المطفأ</h2>\n<p>الشفافية ولون التعبئة المطفأ: عند التحويل من صيغة شفافة إلى JPG، يجب ملء المناطق الشفافة بلون. الأبيض هو الخيار الافتراضي الشائع.</p>\n<p>اختر لون تعبئة يناسب خلفية موقعك أو مستندك. اللون الخاطئ يجعل الصورة تبدو غريبة بعد التحويل.</p>\n<h2 id=\"converting-batches-and-zip-downloads\">كيف تحوّل دفعات وتنزّل ملفات ZIP؟</h2>\n<p>لتحويل دفعات وتنزيل ملفات ZIP، ارفع كل الصور واختر الصيغة نفسها للجميع. الأداة تحوّل الدفعة كاملة وتنزّلها كملف واحد.</p>\n<p>راجع عينة من النتائج قبل الاعتماد على الدفعة كلها. إذا بدت العينة جيدة، فغالبًا بقية الصور بنفس الجودة.</p>\n<h2 id=\"heic-photos-from-iphones\">صور HEIC من آيفون</h2>\n<p>صور HEIC من آيفون صغيرة وكفؤة، لكن كثيرًا من البرامج والبوابات لا تقبلها. التحويل إلى JPG يحل المشكلة فورًا.</p>\n<p>حوّل HEIC إلى JPG قبل رفعها إلى أي بوابة أو برنامج قديم. التحويل من الملف الأصلي يحافظ على الجودة أفضل.</p>\n<h2 id=\"svg-and-vector-files\">ملفات SVG والملفات المتجهة</h2>\n<p>ملفات SVG والملفات المتجهة مختلفة عن الصور العادية: هي تعليمات رسم لا بكسلات. تحويلها إلى PNG يعني رسمها بأبعاد محددة.</p>\n<p>عند تحويل SVG إلى PNG، اختر الأبعاد بعناية. الأبعاد الأكبر تعطي صورة أوضح، لكن بملف أكبر.</p>\n<h2 id=\"checking-quality-before-saving\">كيف تراجع الجودة قبل الحفظ؟</h2>\n<p>راجع الجودة قبل الحفظ: قارن النتيجة بالأصل، وكبّر الصورة وافحص التفاصيل المهمة. إذا بدت النتيجة جيدة، فاحفظها.</p>\n<p>إذا بدت النتيجة أسوأ، فأعد التحويل بجودة أعلى أو صيغة مختلفة. لا تقبل نتيجة سيئة أملًا في أن لا يلاحظها أحد.</p>\n<h2 id=\"privacy-and-local-processing\">الخصوصية: ماذا يحدث لملفاتك؟</h2>\n<p>الخصوصية: ماذا يحدث لملفاتك؟ كل المعالجة تتم محليًا في متصفحك، ولا يُرفع أي ملف إلى خادم. صورك تبقى على جهازك طوال العملية.</p>\n<p>هذا مهم خصوصًا مع الصور الشخصية والمستندات. يمكنك تحويل أي صورة دون قلق بشأن تسرب البيانات.</p>\n<h2 id=\"common-mistakes-to-avoid\">أخطاء شائعة يجب تجنبها</h2>\n<p>أخطاء شائعة يجب تجنبها: التحويل من نسخة مضغوطة أصلًا، واختيار الصيغة الخاطئة للمحتوى، ونسيان لون التعبئة للصور الشفافة.</p>\n<p>تجنب هذه الأخطاء بالبدء من الملف الأصلي واختيار الصيغة حسب المحتوى والوجهة. القليل من الانتباه يمنع معظم المشاكل.</p>\n<h2 id=\"converting-for-different-destinations\">كيف تحوّل لوجهات مختلفة؟</h2>\n<p>للتحويل لوجهات مختلفة، اختر الصيغة حسب الوجهة: JPG للبوابات، وWebP للمواقع الحديثة، وPNG للطباعة والرسوم.</p>\n<p>احتفظ بنسخ متعددة إذا لزم الأمر: نسخة لكل وجهة. النسخ المتعددة أفضل من نسخة واحدة لا تناسب أي وجهة.</p>\n<h2 id=\"file-naming-and-organisation\">أسماء الملفات والتنظيم بعد التحويل</h2>\n<p>أسماء الملفات والتنظيم بعد التحويل: سمِّ الملفات بوضوح حسب المحتوى والصيغة، مثل shaar-mutjar.png. الاسم الواضح يمنع الخلط.</p>\n<p>أنشئ مجلدًا لكل مشروع، وضع فيه النسخ المحوّلة منفصلة عن الأصول. وللتحويل خطوة بخطوة، استخدم <a href=\"/ar/tahwil-as-suwar/\">محول الصور</a>، واقرأ <a href=\"/ar/blog/kayfiyya-tahwil-sighat-as-sura/\">كيفية تحويل صيغة صورة</a> و<a href=\"/ar/blog/faqd-al-jawda-fi-tahwil-sighat-as-suwar/\">تحويل صيغة الصورة: فقدان الجودة</a>، أو جرّب <a href=\"/ar/tahwil-jumli-lis-suwar/\">محول الصور بالجملة</a> للدفعات.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما الفرق بين تحويل صورة وضغطها؟","answer":"التحويل يغيّر صيغة الملف، بينما الضغط يصغّر حجمه. التحويل قد يصغّر الملف أيضًا، لكن هدفه الأساسي تغيير الصيغة لا تقليل الحجم."},{"question":"هل يغيّر تحويل صورة أبعادها بالبكسل؟","answer":"لا، التحويل لا يغيّر أبعاد البكسل افتراضيًا. يحافظ على الأبعاد نفسها ويغيّر طريقة حفظ البيانات فقط. يمكنك تغيير الأبعاد بشكل منفصل إذا أردت."},{"question":"هل يمكنني تحويل صورة دون فقدان الجودة؟","answer":"نعم، إذا حوّلت من صيغة دون فقدان أو بجودة عالية. التحويل من JPG إلى PNG لا يضيف جودة، لكنه لا يفقدها كثيرًا أيضًا. الأفضل أن تحوّل دائمًا من الملف الأصلي."},{"question":"لماذا يحمل ملفي المحوّل اسمًا مختلفًا؟","answer":"لأن الأداة تضيف لاحقة توضح الصيغة الجديدة، مثل sora.jpg إلى sora.png. هذا يمنع الكتابة فوق الملف الأصلي ويساعدك على تمييز النسخ."},{"question":"هل أحتاج إلى تثبيت شيء لتحويل الصور في المتصفح؟","answer":"لا، لا تحتاج إلى تثبيت أي شيء. التحويل يحدث بالكامل في متصفحك، ويعمل على الهاتف والحاسوب دون برامج إضافية."},{"question":"ماذا أفعل إذا بدت صورتي المحوّلة أسوأ من الأصل؟","answer":"تحقق من إعدادات الجودة والصيغة أولًا. التحويل بجودة منخفضة أو إلى صيغة غير مناسبة يفسد النتيجة. أعد التحويل من الملف الأصلي بجودة أعلى."}];
